@startuml

class Aircraft {
  + Model : string
  + ConstructionYear : date
  + NextInspection : date
}

class Contract {
  + Number : int
  + DeliveryConditions : string
  + LegalAspects : string
}

class Acquisition {
  + Model : string
  + Price : double
  + Options : string
  + Customizations : string
  + DeliveryDate : date
}

class Salesperson {
  + Name : string
  + StartDate : date
}

class Airline {
  + Name : string
  + Address : string
  + ParentAirline : Airline
}

Aircraft "1" --|> Contract
Contract "1" -- "*" Acquisition
Salesperson "0..*" -- "0..*" Contract
Airline "0..1" o-- "0..*" Airline

@enduml

